import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    """
    if len(xs) % 2 != 0:
        raise ValueError("Coefficient list must have an even number of elements")

    if xs[-1] == 0:
        raise ValueError("Largest non-zero coefficient must be non-zero")

    # Use the Rational Root Theorem to find potential rational roots
    potential_roots = set()
    for i in range(1, abs(xs[-1]) + 1):
        if xs[-1] % i == 0:
            potential_roots.add(i)
            potential_roots.add(-i)

    # Check potential roots
    for root in potential_roots:
        if math.isclose(poly(xs, root), 0, abs_tol=1e-9):
            return root

    # If no rational root is found, use a numerical method
    # Here we use the bisection method for simplicity
    low, high = -100, 100
    while high - low > 1e-9:
        mid = (low + high) / 2
        if poly(xs, mid) * poly(xs, low) <= 0:
            high = mid
        else:
            low = mid

    return low

