def find_max(words):
    if not words:
        return ""

    max_word = ""
    max_unique_chars = 0

    for word in words:
        unique_chars = len(set(word))
        if unique_chars > max_unique_chars or (unique_chars == max_unique_chars and word < max_word):
            max_word = word
            max_unique_chars = unique_chars

    return max_word

import operator as op

def do_algebra(operator, operand):
    ops = {'+': op.add, '-': op.sub, '*': op.mul, '//': op.floordiv, '**': op.pow}
    result = operand[0]
    for i, op_symbol in enumerate(operator):
        result = ops[op_symbol](result, operand[i + 1])
    return result

